<?php if($success):?><p class="form-message form-message-success"><?php echo safe_output($success);?></p><?php endif;?><?php if($errors):?><ul class="form-message form-message-error"><?php foreach($errors as $e):?><li><?php echo safe_output($e);?></li><?php endforeach;?></ul><?php endif;?><form method="post" class="admin-form profile-form"><?php echo csrf_field();?><div class="form-row"><label>FULL NAME</label><input name="full_name" value="<?php echo safe_output($user['full_name']);?>" required></div><div class="form-row"><label>EMAIL</label><input type="email" name="email" value="<?php echo safe_output($user['email']);?>" required></div><div class="form-row"><label>AGE</label><input type="number" name="age" min="1" max="100" value="<?php echo (int)$user['age'];?>" required></div><div class="profile-password-block"><p class="tech-label">// OPTIONAL_PASSWORD_CHANGE</p><div class="form-row"><label>CURRENT PASSWORD</label><input type="password" name="current_password"></div><div class="form-row-split"><div class="form-row"><label>NEW PASSWORD</label><input type="password" name="new_password" minlength="8"></div><div class="form-row"><label>CONFIRM NEW PASSWORD</label><input type="password" name="confirm_password" minlength="8"></div></div></div><button class="btn btn-primary">SAVE PROFILE <span class="arrow">→</span></button></form>